/**
 * Differential tester: runs the reference executable and the Node port with
 * identical argv and compares stdout, stderr and exit status.
 *
 * The bootloader's `[PYI-<pid>:ERROR]` line embeds the live process id, so that
 * number is normalised before comparison. Nothing else is masked.
 *
 * Usage:
 *   node difftest.mjs            # run the built-in battery
 *   node difftest.mjs -- ARG...  # compare one explicit argv
 */

import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

function normalize(text) {
  return text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function runCase(argv, env) {
  const options = { encoding: 'utf8', env: { ...process.env, ...env } };
  const reference = spawnSync(REFERENCE, argv, options);
  const port = spawnSync('node', [PORT, ...argv], options);
  return {
    argv,
    env,
    ok:
      normalize(reference.stdout ?? '') === normalize(port.stdout ?? '')
      && normalize(reference.stderr ?? '') === normalize(port.stderr ?? '')
      && reference.status === port.status,
    reference: {
      stdout: reference.stdout, stderr: reference.stderr, status: reference.status,
    },
    port: { stdout: port.stdout, stderr: port.stderr, status: port.status },
  };
}

/** Argv vectors covering success, lookup failure and every argparse misuse. */
const CASES = [
  // documented samples
  ['--key', 'a', '--val', '83'],
  ['--key', 'a', '--val', '97'],
  ['--key', 'b', '--val', '21'],
  ['--key', 'b', '--val', '53'],
  // lookup failures
  ['--key', 'c', '--val', '1'],
  ['--key', 'A', '--val', '1'],
  ['--key', '', '--val', '1'],
  ['--key', '1', '--val', '1'],
  ['--key', '2', '--val', '1'],
  ['--key', 'ab', '--val', '1'],
  // repr-sensitive keys
  ["--key", "a'b", '--val', '1'],
  ['--key', 'a"b', '--val', '1'],
  ['--key', 'a\'b"c', '--val', '1'],
  ['--key', 'a\\b', '--val', '1'],
  ['--key', 'a\tb', '--val', '1'],
  ['--key', 'a\nb', '--val', '1'],
  ['--key', '\x01', '--val', '1'],
  ['--key', '\x7f', '--val', '1'],
  ['--key', 'é', '--val', '1'],
  ['--key', '中', '--val', '1'],
  ['--key', '😀', '--val', '1'],
  ['--key', '­', '--val', '1'],
  ['--key', ' ', '--val', '1'],
  ['--key', '​', '--val', '1'],
  ['--key', ' ', '--val', '1'],
  ['--key', 'a b', '--val', '1'],
  ['--key', 'True', '--val', '1'],
  ['--key', 'None', '--val', '1'],
  // missing / required
  [],
  ['--val', '5'],
  ['--key', 'a'],
  ['--key'],
  ['--val'],
  ['--key', '--val', '5'],
  ['--key', 'a', '--val'],
  // help
  ['--help'],
  ['-h'],
  ['--h'],
  ['--he'],
  ['--hel'],
  ['-h', '--key', 'a'],
  ['--key', 'a', '--val', '1', '-h'],
  // abbreviation and equals forms
  ['--key=a', '--val=83'],
  ['--k', 'a', '--v', '1'],
  ['--ke', 'a', '--va', '1'],
  ['--k=a', '--v=1'],
  ['--key=', '--val='],
  ['--key=a=b', '--val', '1'],
  // unrecognized / extras
  ['--key', 'a', '--val', '83', 'extra'],
  ['--key', 'a', '--val', '83', '--bogus', '5'],
  ['--key', 'a', '--val', '1', '-1'],
  ['--key', 'a', '--val', '1', '-'],
  ['-', '--key', 'a', '--val', '1'],
  ['--key', 'a', 'b', '--val', '1'],
  ['--keyy', 'a', '--val', '1'],
  ['-k', 'a', '-v', '1'],
  ['--key', 'a', '--bogus'],
  ['--bogus', '--key', 'a', '--val', '1'],
  // repeated options
  ['--key', 'a', '--key', 'b', '--val', '1'],
  ['--key', 'b', '--key', 'a', '--val', '1'],
  ['--key', 'a', '--val', '1', '--val', '2'],
  ['--key', '--key', '--val', '1'],
  // dash-dash handling
  ['--', '--key', 'a', '--val', '1'],
  ['--key', 'a', '--val', '1', '--'],
  ['--key', 'a', '--', '--val', '1'],
  ['--key', '--', '--val', '1'],
  ['--key', 'a', '--val', '1', '--', 'extra'],
  ['--key=a', '--val=1', '--'],
  ['--', '--'],
  // negative-number-looking values
  ['--key', '-1', '--val', '1'],
  ['--key=-1', '--val', '1'],
  ['--key', '-1.5', '--val', '1'],
  ['--key', '-x', '--val', '1'],
  ['--key', '-1a', '--val', '1'],
  // ordering
  ['--val', '83', '--key', 'a'],
  ['--val=83', '--key=b'],
];

/** Widths that exercise every branch of the usage/help wrapper. */
const WIDTH_ENVS = [
  {}, { COLUMNS: '20' }, { COLUMNS: '24' }, { COLUMNS: '30' }, { COLUMNS: '34' },
  { COLUMNS: '38' }, { COLUMNS: '44' }, { COLUMNS: '48' }, { COLUMNS: '50' },
  { COLUMNS: '60' }, { COLUMNS: '80' }, { COLUMNS: '120' }, { COLUMNS: '11' },
  { COLUMNS: '1' }, { COLUMNS: '0' }, { COLUMNS: 'abc' }, { COLUMNS: '-5' },
];

function main() {
  const explicit = process.argv.indexOf('--');
  if (explicit !== -1) {
    const result = runCase(process.argv.slice(explicit + 1), {});
    console.log(JSON.stringify(result, null, 2));
    process.exit(result.ok ? 0 : 1);
  }

  const failures = [];
  let total = 0;

  for (const argv of CASES) {
    total += 1;
    const result = runCase(argv, {});
    if (!result.ok) failures.push(result);
  }

  // Width sensitivity only shows up on the paths that print usage or help.
  const widthCases = [['--help'], [], ['--val', '5'], ['--key', 'a', '--val', '1', 'extra']];
  for (const env of WIDTH_ENVS) {
    for (const argv of widthCases) {
      total += 1;
      const result = runCase(argv, env);
      if (!result.ok) failures.push(result);
    }
  }

  for (const failure of failures) {
    console.log(`FAIL argv=${JSON.stringify(failure.argv)} env=${JSON.stringify(failure.env)}`);
    console.log(`  ref  status=${failure.reference.status}`);
    console.log(`  port status=${failure.port.status}`);
    if (failure.reference.stdout !== failure.port.stdout) {
      console.log(`  ref  stdout=${JSON.stringify(failure.reference.stdout)}`);
      console.log(`  port stdout=${JSON.stringify(failure.port.stdout)}`);
    }
    if (normalize(failure.reference.stderr) !== normalize(failure.port.stderr)) {
      console.log(`  ref  stderr=${JSON.stringify(failure.reference.stderr)}`);
      console.log(`  port stderr=${JSON.stringify(failure.port.stderr)}`);
    }
  }

  console.log(`\n${total - failures.length}/${total} cases identical`);
  process.exit(failures.length === 0 ? 0 : 1);
}

main();

/**
 * `linecache.getline` emulation.
 *
 * A traceback frame stores the *filename as compiled* -- here the bare relative
 * name `test2.py`. CPython resolves it against the current working directory at
 * the moment the traceback is printed, so whether the offending source line
 * appears depends on where the program was launched from. The reference build
 * behaves exactly this way: run it beside test2.py and the line shows up, run it
 * anywhere else and the frame is header-only.
 */

import { readFileSync } from 'node:fs';

/**
 * Fetches one 1-based line, including its trailing newline, or `''` when the
 * file is unreadable or too short. Mirrors linecache's swallow-all-errors
 * contract.
 *
 * @param {string} filename
 * @param {number} lineno 1-based
 * @returns {string}
 */
export function getline(filename, lineno) {
  let contents;
  try {
    contents = readFileSync(filename, 'utf8');
  } catch {
    return '';
  }
  // Python's `str.splitlines(keepends=True)` for the newline styles that matter.
  const lines = contents.match(/[^\n]*\n|[^\n]+/g) ?? [];
  if (lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

/**
 * `StackSummary._byte_offset_to_character_offset`: code objects record column
 * offsets in UTF-8 bytes, while the caret row is laid out in characters.
 *
 * @param {string} text
 * @param {number} byteOffset
 * @returns {number} character (code point) offset, clamped to the text length
 */
export function byteOffsetToCharacterOffset(text, byteOffset) {
  const bytes = Buffer.from(text, 'utf8');
  const prefix = bytes.subarray(0, byteOffset).toString('utf8');
  return [...prefix].length;
}

/**
 * Number of leading whitespace characters that printing strips off, used to
 * shift the caret row left along with the re-indented source line.
 *
 * @param {string} rawLine
 * @returns {number}
 */
export function strippedCharacterCount(rawLine) {
  return [...rawLine].length - [...rawLine.replace(/^\s+/, '')].length;
}
=====CARET=====
/**
 * The `~^^^` caret row CPython 3.11+ draws beneath the sub-expression that
 * raised.
 *
 * CPython re-parses the failing source segment and, when it is a subscript,
 * marks the object being indexed with `~` and the subscript itself with `^`.
 * When the segment does not parse -- which happens whenever the file on disk no
 * longer matches what was compiled -- it falls back to an undifferentiated run
 * of `^`.
 *
 * Only the subscript shape is recognised here, because that is the only
 * expression this program can fail inside. Anything else takes the fallback,
 * which is also what CPython does for unparseable text.
 */

import { byteOffsetToCharacterOffset, strippedCharacterCount } from './linecache.mjs';

const PRIMARY_CHAR = '~';
const SECONDARY_CHAR = '^';

/**
 * Matches `<primary>[<subscript>]` where the primary is a name/attribute chain.
 * The trailing `]` must close the segment, mirroring a full-segment parse.
 */
const SUBSCRIPT_RE = /^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\[(.*)\]$/;

/**
 * @typedef {object} Anchors
 * @property {number} leftEnd      chars covered by `~` before the subscript
 * @property {number} rightStart   char offset where the trailing `~` run resumes
 */

/**
 * `_extract_caret_anchors_from_line_segment`, restricted to subscripts.
 *
 * @param {string} segment
 * @returns {Anchors|null} null when the segment is not a recognisable subscript
 */
export function extractCaretAnchors(segment) {
  const match = SUBSCRIPT_RE.exec(segment);
  if (match === null) return null;
  const primary = match[1];
  return {
    // `~` spans the object being indexed; `^` spans `[...]` through the close.
    leftEnd: [...primary].length,
    rightStart: [...segment].length,
  };
}

/**
 * Builds the source line and caret row for a frame, given the column offsets
 * recorded in the code object.
 *
 * @param {string} rawLine    line as fetched from disk, trailing newline included
 * @param {number} colno      start column, in UTF-8 bytes
 * @param {number} endColno   end column, in UTF-8 bytes
 * @returns {{source: string, anchor: string|null}|null} null when there is no
 *   line to show at all
 */
export function renderSourceAndAnchor(rawLine, colno, endColno) {
  if (rawLine === '') return null;

  const strippedLine = rawLine.trim();
  const stripped = strippedCharacterCount(rawLine);
  const startOffset = byteOffsetToCharacterOffset(rawLine, colno);
  const endOffset = byteOffsetToCharacterOffset(rawLine, endColno);
  const segment = [...rawLine].slice(startOffset, endOffset).join('');
  const anchors = extractCaretAnchors(segment);

  const span = endOffset - startOffset;
  const strippedLength = [...strippedLine].length;
  // CPython suppresses the caret row when the marked span already covers the
  // whole visible line and there is no `~`/`^` distinction to draw.
  const show = span < strippedLength || (anchors !== null && anchors.rightStart - anchors.leftEnd > 0);
  if (!show) return { source: strippedLine, anchor: null };

  const pad = ' '.repeat(Math.max(startOffset - stripped, 0));
  let carets;
  if (anchors !== null) {
    carets = PRIMARY_CHAR.repeat(anchors.leftEnd)
      + SECONDARY_CHAR.repeat(anchors.rightStart - anchors.leftEnd)
      + PRIMARY_CHAR.repeat(Math.max(span - anchors.rightStart, 0));
  } else {
    carets = SECONDARY_CHAR.repeat(Math.max(span, 0));
  }

  return { source: strippedLine, anchor: `    ${pad}${carets}` };
}

/**
 * Node port of test2.py.
 *
 *   import argparse
 *   from bidict import bidict
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--key', type=str, required=True)
 *   parser.add_argument('--val', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   # 创建双向字典并访问值
 *   b = bidict({'a': 1, 'b': 2})
 *   result = b[args.key]
 *   print(result)
 *
 * Run as: node test2.mjs --key a --val 83
 */

import { ArgumentParser, str } from './lib/argparse/parser.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { print } from './lib/python/sys_io.mjs';
import { PyException, SystemExit } from './lib/python/exceptions.mjs';
import { reportUnhandled } from './lib/runtime/pyinstaller.mjs';

/**
 * The `<module>` frame of test2.py as a traceback sees it. Line 11 is
 * `result = b[args.key]`; columns 9..20 delimit the `b[args.key]` subscript that
 * raises, and are the offsets the code object would carry.
 */
const MODULE_FRAME = Object.freeze({
  file: 'test2.py',
  line: 11,
  name: '<module>',
  colno: 9,
  endColno: 20,
});

/** Name PyInstaller froze the entry script under. */
const SCRIPT_NAME = 'test2';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument(['--key'], { type: str, required: true });
  parser.addArgument(['--val'], { type: str, required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  // 创建双向字典并访问值
  // Passed as explicit pairs so key insertion order and value types (int, not
  // string) survive exactly as they do in the Python literal.
  const b = bidict([
    ['a', 1],
    ['b', 2],
  ]);
  const result = b.getItem(args.key);
  print(result);
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    process.exit(error.code);
  }
  if (error instanceof PyException) {
    // An uncaught Python exception: traceback, then exit status 1.
    reportUnhandled(error, [MODULE_FRAME], SCRIPT_NAME);
    process.exit(1);
  }
  throw error;
}
=====PYI=====
/**
 * Renders an unhandled exception the way the frozen reference build does: a
 * CPython traceback on stderr, followed by PyInstaller's own bootloader notice.
 *
 * Frames are supplied by the raiser, because a JS stack cannot describe the
 * Python call site. A frame carrying column offsets additionally gets its source
 * line looked up on disk and a caret row drawn -- see ./linecache.mjs for why
 * that lookup is cwd-dependent.
 */

import { stderrWrite } from '../python/sys_io.mjs';
import { getline } from './linecache.mjs';
import { renderSourceAndAnchor } from './caret_anchors.mjs';

/** Traceback frames are indented two spaces; source lines four. */
const FRAME_INDENT = '  ';
const SOURCE_INDENT = '    ';

/**
 * @typedef {object} Frame
 * @property {string} file    filename as recorded at compile time
 * @property {number} line
 * @property {string} name    function name, or `<module>` at top level
 * @property {number} [colno]     start column of the failing expression, in bytes
 * @property {number} [endColno]  end column of the failing expression, in bytes
 */

/**
 * Builds the traceback text for an exception.
 *
 * @param {import('../python/exceptions.mjs').PyException} error
 * @param {Frame[]} outerFrames frames above the raising library, outermost first
 * @returns {string}
 */
export function formatTraceback(error, outerFrames) {
  const lines = ['Traceback (most recent call last):'];
  const frames = [...outerFrames, ...(error.frames ?? [])];

  for (const frame of frames) {
    lines.push(`${FRAME_INDENT}File "${frame.file}", line ${frame.line}, in ${frame.name}`);

    if (frame.colno === undefined) continue;
    // Frozen library frames ship no source, and the entry script's source is
    // only present when the process happens to run beside it.
    const rendered = renderSourceAndAnchor(
      getline(frame.file, frame.line),
      frame.colno,
      frame.endColno,
    );
    if (rendered === null) continue;
    lines.push(`${SOURCE_INDENT}${rendered.source}`);
    if (rendered.anchor !== null) lines.push(rendered.anchor);
  }

  lines.push(error.formatExceptionOnly());
  return `${lines.join('\n')}\n`;
}

/**
 * Prints the traceback plus the bootloader's failure notice. The notice embeds
 * the running process id, exactly as the reference build does.
 *
 * @param {import('../python/exceptions.mjs').PyException} error
 * @param {Frame[]} outerFrames
 * @param {string} scriptName name PyInstaller froze the entry script under
 */
export function reportUnhandled(error, outerFrames, scriptName) {
  stderrWrite(formatTraceback(error, outerFrames));
  stderrWrite(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' `
    + 'due to unhandled exception!\n',
  );
}

/**
 * Minimal Python exception hierarchy: just enough for the exceptions this
 * program can raise, plus the traceback metadata needed to reproduce CPython's
 * report.
 */

import { pyRepr } from './repr.mjs';

/**
 * Base class carrying the Python-visible type name and the frames that make up
 * the traceback.
 */
export class PyException extends Error {
  /**
   * @param {string} typeName Python class name, e.g. "KeyError"
   * @param {string} detail   text printed after the colon
   */
  constructor(typeName, detail) {
    super(`${typeName}: ${detail}`);
    this.typeName = typeName;
    this.detail = detail;
    /** @type {Array<{file: string, line: number, name: string, source?: string, anchor?: string}>} */
    this.frames = [];
  }

  /** The final `KeyError: 'c'` style line of a traceback. */
  formatExceptionOnly() {
    return this.detail === '' ? this.typeName : `${this.typeName}: ${this.detail}`;
  }
}

/**
 * `KeyError`'s detail is `repr()` of the missing key, not `str()` -- which is
 * why `KeyError: 'c'` keeps its quotes.
 */
export class PyKeyError extends PyException {
  /** @param {*} key the missing key object */
  constructor(key) {
    super('KeyError', pyRepr(key));
    this.key = key;
  }
}

/** Raised by argparse for an invalid argument; carries the offending action. */
export class ArgumentError extends PyException {
  /**
   * @param {string|null} argumentName rendered name, e.g. "--key"
   * @param {string} message
   */
  constructor(argumentName, message) {
    const detail = argumentName === null ? message : `argument ${argumentName}: ${message}`;
    super('ArgumentError', detail);
    this.argumentName = argumentName;
    this.argMessage = message;
  }

  /** `str(ArgumentError)` -- what argparse feeds to `parser.error()`. */
  toStringPython() {
    return this.detail;
  }
}

/** Mirrors `SystemExit`, used to unwind out of argparse without dying. */
export class SystemExit extends Error {
  /** @param {number} code */
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

