/**
 * Fuzz the traceback source-line lookup: build many cwds containing different
 * `test2.py` files and compare the reference binary with the Node port.
 */
import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, writeFileSync, symlinkSync, chmodSync } from 'node:fs';
import { join } from 'node:path';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';
const ROOT = '/tmp/fuzz/dirs';

const norm = (t) => (t ?? '').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function run(cwd, argv, env = {}) {
  const opts = { encoding: 'buffer', cwd, env: { ...process.env, ...env }, timeout: 20000 };
  const r = spawnSync(REFERENCE, argv, opts);
  const p = spawnSync('node', [PORT, ...argv], opts);
  const dec = (b) => (b ? b.toString('utf8') : '');
  return {
    ref: { stdout: dec(r.stdout), stderr: dec(r.stderr), status: r.status },
    port: { stdout: dec(p.stdout), stderr: dec(p.stderr), status: p.status },
    ok:
      norm(dec(r.stdout)) === norm(dec(p.stdout))
      && norm(dec(r.stderr)) === norm(dec(p.stderr))
      && r.status === p.status,
  };
}

// ---------------------------------------------------------------- builders

const HEAD10 = [
  'import argparse',
  'from bidict import bidict',
  '',
  'parser = argparse.ArgumentParser()',
  "parser.add_argument('--key', type=str, required=True)",
  "parser.add_argument('--val', type=str, required=True)",
  'args = parser.parse_args()',
  '',
  '# comment',
  "b = bidict({'a': 1, 'b': 2})",
];

/** 11-line file whose 11th line is exactly `l11` (trailing newline added). */
function withLine11(l11, { finalNewline = true } = {}) {
  return HEAD10.join('\n') + '\n' + l11 + (finalNewline ? '\n' : '');
}

const cases = [];
function add(name, build, argv = ['--key', 'c', '--val', '1'], env = {}) {
  cases.push({ name, build, argv, env });
}
/** Most cases just need line 11 content. */
function addL11(name, l11, opts) {
  add(name, (d) => writeFileSync(join(d, 'test2.py'), withLine11(l11, opts)));
}

const REAL = 'result = b[args.key]';

// --- presence / absence -------------------------------------------------
add('absent', () => {});
add('real-copy', (d) => {
  writeFileSync(join(d, 'test2.py'),
    spawnSync('cat', ['/workspace/dataset/test2.py'], { encoding: 'buffer' }).stdout);
});
add('empty-file', (d) => writeFileSync(join(d, 'test2.py'), ''));
add('one-line', (d) => writeFileSync(join(d, 'test2.py'), 'x = 1\n'));
add('5-lines', (d) => writeFileSync(join(d, 'test2.py'), HEAD10.slice(0, 5).join('\n') + '\n'));
add('10-lines', (d) => writeFileSync(join(d, 'test2.py'), HEAD10.join('\n') + '\n'));
add('10-lines-no-nl', (d) => writeFileSync(join(d, 'test2.py'), HEAD10.join('\n')));
addL11('exactly-11', REAL);
addL11('exactly-11-no-final-nl', REAL, { finalNewline: false });
add('12-lines', (d) => writeFileSync(join(d, 'test2.py'), withLine11(REAL) + 'print(result)\n'));
add('l11-empty', (d) => writeFileSync(join(d, 'test2.py'), HEAD10.join('\n') + '\n' + '\n'));
addL11('l11-spaces', '    ');
addL11('l11-single-space', ' ');
addL11('l11-tabs', '\t\t');
addL11('l11-space-only-no-nl', '   ', { finalNewline: false });
addL11('l11-formfeed', '\f');
addL11('l11-vtab', '\v');
addL11('l11-nbsp-only', ' ');
addL11('l11-ideographic-space-only', '　');
addL11('l11-zwsp-only', '​');
addL11('l11-filesep-only', '');
addL11('l11-nel-only', '');
addL11('l11-bom-only', '﻿');

// --- lengths ------------------------------------------------------------
addL11('l11-very-long', 'result = b[args.key]' + ' # ' + 'x'.repeat(2000));
addL11('l11-long-prefix', 'x'.repeat(500) + ' = b[args.key]');
addL11('l11-short-ab', 'ab');
addL11('l11-short-ab-no-nl', 'ab', { finalNewline: false });
addL11('l11-1char', 'z');
addL11('l11-1char-no-nl', 'z', { finalNewline: false });
addL11('l11-9bytes', '123456789');
addL11('l11-9bytes-no-nl', '123456789', { finalNewline: false });
