const filter = process.argv[2];
const failures = [];
let total = 0;
for (const [i, c] of cases.entries()) {
  if (filter && !c.name.includes(filter)) continue;
  const dir = join(ROOT, `${String(i).padStart(3, '0')}-${c.name.replace(/[^\w.-]/g, '_')}`);
  mkdirSync(dir, { recursive: true });
  try { c.build(dir); } catch (e) { console.log(`SETUP FAIL ${c.name}: ${e.message}`); continue; }
  total += 1;
  const r = run(dir, c.argv, c.env);
  if (!r.ok) failures.push({ ...c, dir, ...r });
}

for (const f of failures) {
  console.log('='.repeat(72));
  console.log(`FAIL ${f.name}  cwd=${f.dir}  argv=${JSON.stringify(f.argv)} env=${JSON.stringify(f.env)}`);
  console.log(`  ref  status=${f.ref.status}  port status=${f.port.status}`);
  if (norm(f.ref.stdout) !== norm(f.port.stdout)) {
    console.log(`  ref  stdout=${JSON.stringify(f.ref.stdout)}`);
    console.log(`  port stdout=${JSON.stringify(f.port.stdout)}`);
  }
  if (norm(f.ref.stderr) !== norm(f.port.stderr)) {
    console.log(`  ref  stderr=${JSON.stringify(norm(f.ref.stderr))}`);
    console.log(`  port stderr=${JSON.stringify(norm(f.port.stderr))}`);
  }
}
console.log(`\n${total - failures.length}/${total} identical; ${failures.length} failures`);

/**
 * Fuzz the traceback source-line lookup: build many cwds containing different
 * `test2.py` files and compare the reference binary with the Node port.
 */
import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, writeFileSync, symlinkSync, chmodSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';
const ROOT = '/tmp/lcfuzz/dirs';

const norm = (t) => (t ?? '').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function run(cwd, argv, env = {}) {
  const opts = { encoding: 'buffer', cwd, env: { ...process.env, ...env }, timeout: 20000 };
  const r = spawnSync(REFERENCE, argv, opts);
  const p = spawnSync('node', [PORT, ...argv], opts);
  const dec = (b) => (b ? b.toString('utf8') : '');
  return {
    ref: { stdout: dec(r.stdout), stderr: dec(r.stderr), status: r.status },
    port: { stdout: dec(p.stdout), stderr: dec(p.stderr), status: p.status },
    ok:
      norm(dec(r.stdout)) === norm(dec(p.stdout))
      && norm(dec(r.stderr)) === norm(dec(p.stderr))
      && r.status === p.status,
  };
}

