/** Round 2: targeted probes. */
import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, writeFileSync, chmodSync } from 'node:fs';
import { join } from 'node:path';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';
const ROOT = '/tmp/lcfuzz/dirs2';
const norm = (t) => (t ?? '').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function run(cwd, argv, env = {}, uid) {
  const opts = { encoding: 'buffer', cwd, env: { ...process.env, ...env }, timeout: 20000 };
  if (uid !== undefined) { opts.uid = uid; opts.gid = uid; }
  const r = spawnSync(REFERENCE, argv, opts);
  const p = spawnSync('node', [PORT, ...argv], opts);
  const dec = (b) => (b ? b.toString('utf8') : '');
  return {
    ref: { stdout: dec(r.stdout), stderr: dec(r.stderr), status: r.status, err: r.error?.message },
    port: { stdout: dec(p.stdout), stderr: dec(p.stderr), status: p.status, err: p.error?.message },
    ok: norm(dec(r.stdout)) === norm(dec(p.stdout))
      && norm(dec(r.stderr)) === norm(dec(p.stderr)) && r.status === p.status,
  };
}

const HEAD10 = [
  'import argparse', 'from bidict import bidict', '',
  'parser = argparse.ArgumentParser()',
  "parser.add_argument('--key', type=str, required=True)",
  "parser.add_argument('--val', type=str, required=True)",
  'args = parser.parse_args()', '', '# comment', "b = bidict({'a': 1, 'b': 2})",
];
const REAL = 'result = b[args.key]';
const withL11 = (l, nl = true) => HEAD10.join('\n') + '\n' + l + (nl ? '\n' : '');

const cases = [];
const add = (name, build, argv = ['--key', 'c', '--val', '1'], env = {}, uid) =>
  cases.push({ name, build, argv, env, uid });
const addL11 = (name, l, nl) => add(name, (d) => writeFileSync(join(d, 'test2.py'), withL11(l, nl)));

// lone \r inside line 11 -> Python universal newlines splits, JS does not
addL11('cr-inside-l11', 'res\rult = b[args.key]');
addL11('cr-then-space-l11', REAL + '\r ');
addL11('cr-then-text-l11', REAL + '\rXYZ');
addL11('crlf-plus-trailing-space', REAL + ' \r');

// indented + subscript segment
addL11('indent9-subscript', ' '.repeat(9) + 'b[args.key]');
addL11('indent9-subscript-trailing', ' '.repeat(9) + 'b[args.key]  ');
addL11('indent4-subscript', ' '.repeat(4) + 'xxxxx b[args.key]');

// display width variants
addL11('ambiguous-width', '±±±±±±±±± = b[args.key]');
addL11('watch-emoji-wide', '⌚⌚ = b[args.key]');
addL11('halfwidth-kana', 'ｱｱｱｱｱｱｱｱｱ = b[k]');
addL11('wide-with-negative-pad', ' '.repeat(20) + '中 = b[args.key]');
addL11('cjk-trailing-comment-wide', 'result = b[args.key] # 中');

// caret-row eating (negative pad) with tabs
addL11('indent-20tabs', '\t'.repeat(20) + REAL);
addL11('indent-13sp', ' '.repeat(13) + REAL);
addL11('indent-14sp', ' '.repeat(14) + REAL);
addL11('indent-15sp', ' '.repeat(15) + REAL);
addL11('indent-11sp', ' '.repeat(11) + REAL);
addL11('indent-12sp', ' '.repeat(12) + REAL);

// short lines with/without trailing newline
addL11('l11-2bytes-no-nl', 'xy', false);
addL11('l11-8bytes-no-nl', '12345678', false);
addL11('l11-10bytes-no-nl', '1234567890', false);
addL11('l11-20bytes-no-nl', '12345678901234567890', false);
addL11('l11-21bytes-no-nl', '123456789012345678901', false);
addL11('l11-empty-no-nl', '', false);
addL11('l11-tab-only-no-nl', '\t', false);

// non-subscript ast shapes
addL11('binop', 'result = aa + bbbbbb');
addL11('binop2', 'z = aaaa + bbbbbbb');
addL11('call', 'result = fn(a, b, c)');
addL11('attr-access', 'result = aaa.bbbb.ccc');
addL11('dict-sub-str', "result = d['aaaaa']");
addL11('unary', 'result = -aaaaaaaaa');
addL11('compare', 'result = a < bbbbbbb');
addL11('await-sub', 'r = await bb[args.k]');
addL11('genexp', 'r = [q for q in bbb]');

// PYTHONPATH / sys.path fallback (no test2.py in cwd)
mkdirSync('/tmp/lcfuzz/pp', { recursive: true });
writeFileSync('/tmp/lcfuzz/pp/test2.py', withL11(REAL));
add('pythonpath-lookup', () => {}, ['--key', 'c', '--val', '1'],
  { PYTHONPATH: '/tmp/lcfuzz/pp' });

// unreadable file, as an unprivileged user
add('chmod000-as-nobody', (d) => {
  writeFileSync(join(d, 'test2.py'), withL11(REAL));
  chmodSync(join(d, 'test2.py'), 0o000);
  chmodSync(d, 0o777);
}, ['--key', 'c', '--val', '1'], {}, 65534);
add('readable-as-nobody', (d) => {
  writeFileSync(join(d, 'test2.py'), withL11(REAL));
  chmodSync(join(d, 'test2.py'), 0o644);
  chmodSync(d, 0o777);
}, ['--key', 'c', '--val', '1'], {}, 65534);

rmSync(ROOT, { recursive: true, force: true });
mkdirSync(ROOT, { recursive: true });
const failures = [];
let total = 0;
for (const [i, c] of cases.entries()) {
  const dir = join(ROOT, `${String(i).padStart(3, '0')}-${c.name.replace(/[^\w.-]/g, '_')}`);
  mkdirSync(dir, { recursive: true });
  c.build(dir);
  total += 1;
  const r = run(dir, c.argv, c.env, c.uid);
  if (!r.ok) failures.push({ ...c, dir, ...r });
}
for (const f of failures) {
  console.log('='.repeat(72));
  console.log(`FAIL ${f.name}\n  cwd=${f.dir}\n  argv=${JSON.stringify(f.argv)} env=${JSON.stringify(f.env)} uid=${f.uid}`);
  console.log(`  ref status=${f.ref.status} err=${f.ref.err}  port status=${f.port.status} err=${f.port.err}`);
  if (norm(f.ref.stdout) !== norm(f.port.stdout)) {
    console.log(`  ref  stdout=${JSON.stringify(f.ref.stdout)}`);
    console.log(`  port stdout=${JSON.stringify(f.port.stdout)}`);
  }
  if (norm(f.ref.stderr) !== norm(f.port.stderr)) {
    console.log(`  ref  stderr=${JSON.stringify(norm(f.ref.stderr))}`);
    console.log(`  port stderr=${JSON.stringify(norm(f.port.stderr))}`);
  }
}
console.log(`\nTOTAL=${total} IDENTICAL=${total - failures.length} FAILURES=${failures.length}`);

