import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';

const HEAD10 = ['import argparse', 'from bidict import bidict', '', 'parser = argparse.ArgumentParser()',
  "parser.add_argument('--key', type=str, required=True)", "parser.add_argument('--val', type=str, required=True)",
  'args = parser.parse_args()', '', '# comment', "b = bidict({'a': 1, 'b': 2})"];

const samples = {
  spaces4: '    ', vtab: '', formfeed: ' ', nbsp: ' ', zwsp: '​',
  filesep: '', nel: '', bomchar: '﻿', ideo: '　', empty: '',
  tab: '\t', nul: '�', esc: '', cjk1: '中', a: 'a', ab: 'ab',
  nbsp2: '  ', vtab2: '', sp_vtab: ' ', vtab_sp: ' ',
  sp_cjk: ' 中', tab_nbsp: '\t ', bel: '', del: '',
};

rmSync('/tmp/lcfuzz/m', { recursive: true, force: true });
const esc = (s) => JSON.stringify(s).replace(/[-￿]/g,
  (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
for (const [k, v] of Object.entries(samples)) {
  const d = `/tmp/lcfuzz/m/${k}`;
  mkdirSync(d, { recursive: true });
  writeFileSync(`${d}/test2.py`, HEAD10.join('\n') + '\n' + v + '\n');
  const opt = { cwd: d, encoding: 'utf8' };
  const r = spawnSync('/workspace/dataset/test2_executable', ['--key', 'c', '--val', '1'], opt);
  const p = spawnSync('node', ['/output/test2.mjs', '--key', 'c', '--val', '1'], opt);
  const mid = (s) => s.split('\n').slice(2, -4);
  const rm = mid(r.stderr); const pm = mid(p.stderr);
  const same = JSON.stringify(rm) === JSON.stringify(pm);
  console.log((same ? 'ok   ' : 'DIFF ') + k.padEnd(9), 'l11=' + esc(v).padEnd(14),
    'REF=' + esc(JSON.stringify(rm)).padEnd(34), 'PORT=' + esc(JSON.stringify(pm)));
}
